import {useState} from "react";
export const STATUSES=["OPEN","IN_PROGRESS","CLOSED"] as const;export type Status=(typeof STATUSES)[number];export type StatusFilter=Status|"ALL";export type View="table"|"cards";export type Ticket={id:number;title:string;status:Status};
export function isStatusFilter(value:string):value is StatusFilter{return value==="ALL"||STATUSES.some(status=>status===value);}
export function filterTickets(tickets:readonly Ticket[],status:StatusFilter):Ticket[]{return tickets.filter(ticket=>status==="ALL"||ticket.status===status);}
export function statusCounts(tickets:readonly Ticket[]):Record<StatusFilter,number>{return {ALL:tickets.length,OPEN:tickets.filter(ticket=>ticket.status==="OPEN").length,IN_PROGRESS:tickets.filter(ticket=>ticket.status==="IN_PROGRESS").length,CLOSED:tickets.filter(ticket=>ticket.status==="CLOSED").length};}
export function Dashboard({tickets}:{tickets:readonly Ticket[]}){const [query,setQuery]=useState("");const [status,setStatus]=useState<StatusFilter>("ALL");const [requestedPage,setRequestedPage]=useState(1);const [selectedId,setSelectedId]=useState<number|null>(null);const normalized=query.trim().toLowerCase();const visible=filterTickets(tickets,status).filter(ticket=>ticket.title.toLowerCase().includes(normalized));const count=visible.length;const pageCount=Math.max(1,Math.ceil(count/10));const page=Math.max(1,Math.min(requestedPage,pageCount));const pageItems=visible.slice((page-1)*10,page*10);const selected=tickets.find(ticket=>ticket.id===selectedId)??null;return <main><h1>Audyt zbędnych efektów</h1><label>Szukaj<input value={query} onChange={event=>{setQuery(event.currentTarget.value);setRequestedPage(1);}}/></label><label>Status<select value={status} onChange={event=>{const next=event.currentTarget.value;if(isStatusFilter(next)){setStatus(next);setRequestedPage(1);}}}>{["ALL",...STATUSES].map(value=><option key={value}>{value}</option>)}</select></label><p>Wyników: {count}; strona {page}/{pageCount}</p><ul>{pageItems.map(ticket=><li key={ticket.id}><button type="button" aria-pressed={ticket.id===selectedId} onClick={()=>setSelectedId(ticket.id)}>{ticket.title}</button></li>)}</ul><button type="button" disabled={page<=1} onClick={()=>setRequestedPage(page-1)}>Poprzednia</button><button type="button" disabled={page>=pageCount} onClick={()=>setRequestedPage(page+1)}>Następna</button><p>{selected?"Wybrano #"+selected.id+": "+selected.title:"Nic nie wybrano"}</p></main>;}

